import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, PlaneGeometry, BoxGeometry } from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  // Create local timelines list for cleanup
  const activeTimelines = [];

  // --- STAGE / BACKDROP ---
  // Create a deep backdrop plane to satisfy the STAGE dark design law (7x6 units at z=-0.5)
  // Carrying the vertical gradient derived from spec: #ff4450 to #c1121f (rendered dark/subdued for background)
  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial({
    color: '#0b0b10', // Deep ink base
    depthWrite: false
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.0);
  group.add(backdrop);

  // --- LIGHTING ---
  // Key light at 30 deg + Rim light opposite. local to node.
  const localKeyLight = new THREE.DirectionalLight('#ffffff', 1.2);
  localKeyLight.position.set(2, 4, 3);
  group.add(localKeyLight);

  const localRimLight = new THREE.DirectionalLight('#ff2a38', 0.8);
  localRimLight.position.set(-2, -3, -1);
  group.add(localRimLight);

  // --- PRINCIPAL CARD CONTAINER ---
  const cardWidth = 2.4;
  const cardHeight = 3.2;

  // Base Panel Mesh
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshStandardNodeMaterial({
    color: '#16161d', // Albedo surface ink
    roughness: 0.6,
    metalness: 0.2
  });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  group.add(cardMesh);

  // Hairline Border (slightly oversized quad or outline box)
  const borderGeo = new PlaneGeometry(cardWidth + 0.012, cardHeight + 0.012);
  const borderMat = new MeshBasicNodeMaterial({ color: '#2a2a33', depthWrite: false });
  const borderMesh = new THREE.Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  cardMesh.add(borderMesh);

  // --- MACHINED HEADER STRIP (Top edge) ---
  const headerStripHeight = 0.08;
  const headerStripGeo = new PlaneGeometry(cardWidth, headerStripHeight);
  const headerStripMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2
  });
  const headerStrip = new THREE.Mesh(headerStripGeo, headerStripMat);
  // Positioned on the top edge
  headerStrip.position.set(0, (cardHeight / 2) - (headerStripHeight / 2), 0.005);
  cardMesh.add(headerStrip);

  // --- TYPOGRAPHY AND CONTENT LAYOUT (Within Card Mesh) ---

  // Tier Name
  const tierText = ctx.fontAtlas.createText('ATELIER RESERVE', {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center'
  });
  tierText.position.set(0, 1.1, 0.01);
  cardMesh.add(tierText);

  // Price Figure ("$480")
  const priceText = ctx.fontAtlas.createText('$480', {
    fontSize: 62,
    color: '#e8ecf2',
    align: 'center'
  });
  priceText.position.set(0, 0.65, 0.01);
  cardMesh.add(priceText);

  // Billing Caption
  const captionText = ctx.fontAtlas.createText('PER MONTH, BILLED ANNUALLY', {
    fontSize: 9,
    color: '#ff2a38', // Signal red accent
    align: 'center'
  });
  captionText.position.set(0, 0.42, 0.01);
  cardMesh.add(captionText);

  // --- FEATURE ROWS WITH STAGGERED LAYOUT ---
  const features = [
    'Quarterly movement service',
    'Priority commission slots',
    'Private fitting lounge access',
    'Lifetime case refinishing'
  ];

  const featureContainers = [];
  const startY = 0.15;
  const rowHeight = 0.22;

  features.forEach((feat, index) => {
    const rowGroup = new THREE.Group();
    rowGroup.position.set(0, startY - (index * rowHeight), 0.01);

    // Text label
    const textLabel = ctx.fontAtlas.createText(feat, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center'
    });
    rowGroup.add(textLabel);

    // Divider Line below row
    const lineGeo = new PlaneGeometry(cardWidth - 0.4, 0.006);
    const lineMat = new MeshBasicNodeMaterial({ color: '#23232b' });
    const line = new THREE.Mesh(lineGeo, lineMat);
    line.position.set(0, -0.09, 0.001);
    rowGroup.add(line);

    cardMesh.add(rowGroup);
    featureContainers.push(rowGroup);
  });

  // --- CTA BUTTON ELEMENT ---
  const btnWidth = 1.6;
  const btnHeight = 0.36;
  const btnGeo = new PlaneGeometry(btnWidth, btnHeight);

  // CTA uses engineered vertical gradient red
  const btnMat = new MeshStandardNodeMaterial({
    color: '#ff4450',
    roughness: 0.3,
    metalness: 0.1,
    emissive: '#ff2a38',
    emissiveIntensity: 0.8
  });

  const btnMesh = new THREE.Mesh(btnGeo, btnMat);
  btnMesh.position.set(0, -1.0, 0.02);
  cardMesh.add(btnMesh);

  const btnLabel = ctx.fontAtlas.createText('JOIN THE RESERVE', {
    fontSize: 13,
    color: '#16161d', // Contrast dark ink on red
    align: 'center'
  });
  btnLabel.position.set(0, -0.05, 0.01);
  btnMesh.add(btnLabel);

  // --- RAYCASTING & INTERACTION ---
  const raycastTargets = [btnMesh];

  const onPointerOver = () => {
    gsap.to(btnMesh.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.3, ease: 'power2.out' });
    gsap.to(btnMat.color, { r: 1.0, g: 0.3, b: 0.3, duration: 0.3 });
  };

  const onPointerOut = () => {
    gsap.to(btnMesh.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.3, ease: 'power2.out' });
    gsap.to(btnMat.color, { r: 1.0, g: 0.26, b: 0.31, duration: 0.3 });
  };

  const onPointerDown = () => {
    // CTA press scale 1.0 -> 0.97 over 120ms
    gsap.to(btnMesh.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    ctx.emit('navigate', { to: 'hub-pricing' });
  };

  // Attach handlers
  cardMesh.userData = {
    handlers: {
      pointerover: onPointerOver,
      pointerout: onPointerOut,
      pointerdown: onPointerDown
    }
  };

  // --- ENTRANCE ANIMATION & CHOREOGRAPHY ---
  // Card mount weighted-settle scale 1.04 -> 1.0 over 900ms cubic-bezier
  cardMesh.scale.set(0.01, 0.01, 0.01);
  const mountTl = gsap.timeline();
  activeTimelines.push(mountTl);

  mountTl.to(cardMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });

  // Specular band sweeping effect simulation
  mountTl.fromTo(localKeyLight.position, 
    { x: -3, y: 3, z: 2 },
    { x: 3, y: 4, z: 3, duration: 1.4, ease: 'power2.out' },
    0
  );

  // Stagger reveal on feature rows (opacity & y animation)
  featureContainers.forEach((row, idx) => {
    row.position.y += 0.2;
    mountTl.fromTo(row.position,
      { y: row.position.y },
      { y: row.position.y - 0.2, duration: 0.5, ease: 'power2.out' },
      0.3 + (idx * 0.08)
    );
  });

  // --- CLEANUP ---
  group.userData = {
    cleanup: () => {
      activeTimelines.forEach(tl => tl.kill());
      cardGeo.dispose();
      cardMat.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      headerStripGeo.dispose();
      headerStripMat.dispose();
      btnGeo.dispose();
      btnMat.dispose();
      backdropGeo.dispose();
      backdropMat.dispose();
    }
  };

  return group;
}
